const sviBindingsOf=(profile:VlanService):VlanSviBinding[]=>{const bindings=profile.sviBindings||[];if(bindings.length)return bindings;const vlanId=portModeOf(profile)==='trunk'?nativeVlanOf(profile):profile.vlanId;return vlanId===undefined?[]:[{id:`legacy-${profile.id}`,vlanId,gatewayAddress:profile.gatewayAddress||''}]};
const primarySviBindingOf=(profile:VlanService)=>sviBindingsOf(profile)[0];
