  const sviBindingSummaryOf=(profile:VlanService)=>sviBindingsOf(profile).map(binding=>`VLAN ${binding.vlanId??'-'}${binding.gatewayAddress?` - ${binding.gatewayAddress}`:' - L2 only'}`).join(' - ');
const vlanListValid=(value:string)=>{const text=value.trim();if(!text)return false;return text.split(',').every(part=>{const ranges=part.trim().split('-').map(Number);return ranges.length<=2&&ranges.every(item=>Number.isInteger(item)&&item>=1&&item<=4094)&&(ranges.length===1||ranges[0]<=ranges[1])})};
const stepSummaryOf=(profile:VlanService)=>{const steps:string[]=[];if(vlanStepEnabledOf(profile))steps.push(`VLAN +${vlanStepOf(profile)}`);if(gatewayStepEnabledOf(profile))steps.push(`Gateway +${gatewayStepOf(profile)}`);return steps.join(' - ')};
const deviceOrderOf=(profile:VlanService):VlanDeviceOrder=>profile.deviceOrder||'hostname-asc';
const assignmentsOf=(profile:VlanService)=>profile.interfaceAssignments||[];
