type NetworkVlanOption={id:number;description:string};
const selectedNetworkVlanIds=(value:string)=>{const ids=value.split(',').flatMap(part=>{const match=part.trim().match(/^(\d+)(?:-(\d+))?$/);if(!match)return[];const start=Number(match[1]),end=Number(match[2]??match[1]);if(!Number.isInteger(start)||!Number.isInteger(end)||start<1||end>4094||start>end)return[];return Array.from({length:end-start+1},(_,index)=>start+index)});return[...new Set(ids)].sort((left,right)=>left-right)};
const formatNetworkVlanIds=(values:number[])=>{const ids=[...new Set(values.filter(value=>Number.isInteger(value)&&value>=1&&value<=4094))].sort((left,right)=>left-right);const ranges:string[]=[];for(let index=0;index<ids.length;){const start=ids[index];let end=start;while(ids[index+1]===end+1){end=ids[++index]}ranges.push(start===end?String(start):`${start}-${end}`);index++}return ranges.join(',')};
const NetworkVlanSelect=({value,options,disabled,onChange,ariaLabel}:{value?:number;options:NetworkVlanOption[];disabled:boolean;onChange:(value:number|undefined)=>void;ariaLabel:string})=>{const [query,setQuery]=useState('');const text=query.trim();const requested=Boolean(text)&&vlanListValid(text)?new Set(selectedNetworkVlanIds(text)):undefined;const filtered=requested?options.filter(option=>requested.has(option.id)):options.filter(option=>`${option.id} ${option.description}`.toLowerCase().includes(text.toLowerCase())).slice(0,100);const selectedOption=options.find(option=>option.id===value);const selectedLabel=value===undefined?'Search or enter VLAN ID':`VLAN ${value}${selectedOption?.description?' - '+selectedOption.description:''}`;const choose=(vlanId:number)=>{onChange(vlanId);setQuery('')};return <details className="group relative"><summary aria-label={ariaLabel} aria-disabled={disabled} onClick={event=>disabled&&event.preventDefault()} className={`${compactInput} flex cursor-pointer list-none items-center justify-between gap-2 ${disabled?'cursor-not-allowed bg-slate-100 text-slate-400':''}`}><span className="truncate">{selectedLabel}</span><ChevronDown size={11} className="flex-shrink-0 transition group-open:rotate-180"/></summary>{!disabled&&<div className="absolute left-0 top-full z-40 mt-1 w-72 rounded border border-slate-200 bg-white p-2 shadow-lg"><input autoFocus aria-label={`${ariaLabel} Network search`} value={query} onChange={event=>setQuery(event.target.value)} onKeyDown={event=>{if(event.key==='Enter'&&enteredValid){event.preventDefault();choose(entered)}}} placeholder="Search Network or enter VLAN ID" className="h-8 w-full rounded border border-slate-300 px-2 text-[8px] outline-none focus:border-blue-500"/>{enteredValid&&!options.some(option=>option.id===entered)&&<button type="button" onClick={()=>choose(entered)} className="mt-1 w-full rounded px-2 py-1.5 text-left text-[8px] font-medium text-blue-700 hover:bg-blue-50">Use VLAN {entered}</button>}<div className="mt-1 max-h-44 overflow-auto">{filtered.map(option=><button type="button" key={option.id} onClick={()=>choose(option.id)} className={`flex w-full items-center gap-2 rounded px-2 py-1.5 text-left text-[8px] hover:bg-blue-50 ${option.id===value?'bg-blue-50 text-blue-700':'text-slate-700'}`}><span className="font-mono">{option.id}</span>{option.description&&<span className="truncate text-slate-400">路 {option.description}</span>}</button>)}{!filtered.length&&<span className="block px-2 py-2 text-[8px] text-slate-400">No matching Network VLANs.</span>}</div></div>}</details>};
