  const networkVlanOptions=useMemo<NetworkVlanOption[]>(()=>{const options=new Map<number,string>();networkBindings.forEach(binding=>{if(Number.isInteger(binding.vlanId)&&binding.vlanId!>=1&&binding.vlanId!<=4094&&!options.has(binding.vlanId!))options.set(binding.vlanId!,binding.vlanInterface?.trim()||binding.description?.trim()||'')});return[...options].sort(([left],[right])=>left-right).map(([id,description])=>({id,description}))},[networkBindings]);
