          if(effective.portMode==='trunk'&&!vlanListValid(effective.allowedVlans))errors.push(`${profileName} ${device?.hostname||deviceId} ${interfaceName} requires valid Allowed VLANs.`);
          if(effective.gatewayAddress&&!sviGatewayAddressValid(effective.gatewayAddress))errors.push(`${profileName} ${device?.hostname||deviceId} ${interfaceName} requires a usable SVI IP host address in IPv4/CIDR notation.`);if(gatewayStepEnabledOf(profile)&&profile.gatewayAddress&&!effective.gatewayAddress)errors.push(`${profileName} ${device?.hostname||deviceId} ${interfaceName} Gateway allocation exceeds IPv4 address space.`);
