  const autoSaveSignature=useMemo(()=>JSON.stringify({configurationName:draft.configurationName,fabricId:draft.fabricId,services:draft.services,networkSviBindings:draft.networkSviBindings,directInterfaceAssignments:draft.directInterfaceAssignments}),[draft.configurationName,draft.directInterfaceAssignments,draft.fabricId,draft.networkSviBindings,draft.services]);
