  const sectionIndex=sections.findIndex(item=>item.id===section);
  const changeSection=(next:SectionId)=>{setSection(next);setProfilePickerOpen(false);if(next==='configuration')setConfigurationView('network');else{setAssignmentProfileId('');setAssignmentDeviceId(null)}};

  const renderProfileList=()=> <div className="flex min-h-0 flex-1 flex-col bg-white">
    <WorkbenchHeader title="VLAN Service Profiles" description="Create business-access profiles. For AI RoCE, use RoCE Access to plan one shared VLAN, subnet and Leaf SVI for each H100 NIC rail." action={<button disabled={!workspace} onClick={addProfile} className={primaryClass}><Plus size={11}/>Create Profile</button>}/>
    <div className="flex flex-shrink-0 justify-end border-b border-slate-200 bg-slate-50/70 px-4 py-2.5"><div className="relative w-56"><Search size={11} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-400"/><input value={profileQuery} onChange={event=>setProfileQuery(event.target.value)} placeholder="Search Profiles" className="h-8 w-full border border-slate-300 bg-white pl-7 pr-2 text-[8px] outline-none focus:border-blue-400"/></div></div>
    <div className="min-h-0 flex-1 overflow-auto px-3 py-2"><table style={{width:'100%',minWidth:'100%'}} className="table-fixed text-left text-[8px]"><colgroup><col style={{width:'17%'}}/><col style={{width:'14%'}}/><col style={{width:'9%'}}/><col style={{width:'11%'}}/><col style={{width:'12%'}}/><col style={{width:'15%'}}/><col style={{width:'10%'}}/><col style={{width:'5%'}}/></colgroup><thead className={tableHead}><tr><SortHeader label="Profile Name" active={profileSort.key==='name'} direction={profileSort.direction} onClick={()=>toggleProfileSort('name')}/><th className={tableCell}>Description</th><SortHeader label="Port Mode" active={profileSort.key==='portMode'} direction={profileSort.direction} onClick={()=>toggleProfileSort('portMode')}/><SortHeader label="VLAN / Native VLAN" active={profileSort.key==='vlan'} direction={profileSort.direction} onClick={()=>toggleProfileSort('vlan')}/><SortHeader label="Allowed VLANs" active={profileSort.key==='allowedVlans'} direction={profileSort.direction} onClick={()=>toggleProfileSort('allowedVlans')}/><SortHeader label="SVI IP" active={profileSort.key==='sviGateway'} direction={profileSort.direction} onClick={()=>toggleProfileSort('sviGateway')}/><th className={tableCell}>Operation</th></tr></thead><tbody className="divide-y divide-slate-100">{filteredProfiles.map(profile=>{return <tr key={profile.id} className="hover:bg-slate-50"><td className={tableCell}><button onClick={()=>openProfile(profile)} className="text-left"><b className="block truncate text-[9px] text-blue-700 hover:underline">{profile.name||'Unnamed Profile'}</b></button></td><td className={`${tableCell} truncate text-slate-500`}>{profile.description||'-'}</td><td className={`${tableCell} capitalize text-slate-600`}>{portModeOf(profile)}</td><td className={`${tableCell} font-mono font-semibold text-slate-700`}>{sviBindingsOf(profile).map(binding=>binding.vlanId??'-').join(', ')||'-'}</td><td className={`${tableCell} truncate font-mono text-slate-600`}>{portModeOf(profile)==='trunk'?allowedVlansOf(profile)||'-':'-'}</td><td title={sviBindingSummaryOf(profile)||'-'} className={`${tableCell} truncate font-mono text-slate-600`}>{sviBindingSummaryOf(profile)||'-'}</td><td className={tableCell}><button title="Edit Profile" onClick={()=>openProfile(profile)} className="mr-1 rounded p-1.5 text-blue-600 hover:bg-blue-50"><Pencil size={12}/></button><button disabled={true} title="Delete Profile" onClick={()=>removeProfile(profile)} className="rounded p-1.5 text-red-600 hover:bg-red-50 disabled:opacity-40"><Trash2 size={12}/></button></td></tr>})}{!filteredProfiles.length&&<EmptyTable colSpan={7}>No VLAN Service Profiles match this search.</EmptyTable>}</tbody></table></div>
  </div>;

  const updateSviBindings=(bindings:VlanSviBinding[])=>{if(!active)return;const baseVlan=portModeOf(active)==='access'?active.vlanId:nativeVlanOf(active);const primary=bindings.find(binding=>binding.vlanId===baseVlan)||bindings[0];const hasGateway=bindings.some(binding=>Boolean(binding.gatewayAddress.trim()));update({sviBindings:bindings,gatewayAddress:primary?.gatewayAddress||'',sviEnabled:hasGateway,gatewayMode:hasGateway?'single':'none',allocationMode:allocationModeOf(active)});};
  const updateSviBinding=(bindingId:string,patch:Partial<VlanSviBinding>)=>{if(!active)return;updateSviBindings(sviBindingsOf(active).map(binding=>binding.id===bindingId?{...binding,...patch}:binding));};
  const addSviBinding=()=>{if(!active)return;const used=new Set(sviBindingsOf(active).map(binding=>binding.vlanId).filter((vlanId):vlanId is number=>Number.isInteger(vlanId)));let vlanId=(Math.max(0,...used)+1)||1;while(used.has(vlanId)&&vlanId<=4094)vlanId++;updateSviBindings([...sviBindingsOf(active),{id:sviBindingId(),vlanId:vlanId<=4094?vlanId:undefined,gatewayAddress:''}]);};
  const removeSviBinding=(bindingId:string)=>{if(!active)return;updateSviBindings(sviBindingsOf(active).filter(binding=>binding.id!==bindingId));};
  const renderSviBindingEditor=(profile:VlanService)=><section className="col-span-2 border border-slate-200 bg-slate-50/50"><header className="flex items-center justify-between border-b border-slate-200 bg-white px-4 py-3"><div><h3 className="text-[10px] font-semibold text-slate-800">VLAN &amp; SVI IP Bindings</h3><p className="mt-1 text-[8px] text-slate-400">Each SVI IP is bound to one VLAN. Leave the gateway blank for Layer 2 only.</p></div><button type="button" disabled={true} onClick={addSviBinding} className={`${buttonClass} h-8 px-3`}><Plus size={11}/>Add VLAN</button></header><div className="overflow-auto px-3 py-2"><table className="w-full min-w-[620px] table-fixed text-left text-[8px]"><colgroup><col className="w-[26%]"/><col className="w-[58%]"/><col className="w-[16%]"/></colgroup><thead className="bg-slate-100 text-[8px] uppercase tracking-wide text-slate-500"><tr><th className="px-3 py-2.5">VLAN ID</th><th className="px-3 py-2.5">SVI IP</th><th className="px-3 py-2.5 text-right">Action</th></tr></thead><tbody className="divide-y divide-slate-200 bg-white">{sviBindingsOf(profile).map(binding=><tr key={binding.id}><td className="px-3 py-2.5"><input type="number" min={1} max={4094} disabled={true} value={binding.vlanId??''} onChange={event=>updateSviBinding(binding.id,{vlanId:event.target.value===''?undefined:Number(event.target.value)})} className="h-8 w-full rounded border border-slate-300 bg-white px-2.5 text-[8px] text-slate-700 outline-none focus:border-blue-500 disabled:bg-slate-100"/></td><td className="px-3 py-2.5"><input disabled={true} value={binding.gatewayAddress} onChange={event=>updateSviBinding(binding.id,{gatewayAddress:event.target.value})} placeholder="IPv4/CIDR - optional for Layer 2 only" className="h-8 w-full rounded border border-slate-300 bg-white px-2.5 text-[8px] text-slate-700 outline-none focus:border-blue-500 disabled:bg-slate-100"/></td><td className="px-3 py-2.5 text-right"><button type="button" disabled={!workspace||sviBindingsOf(profile).length===1} onClick={()=>removeSviBinding(binding.id)} title="Remove VLAN-SVI binding" className="rounded p-1.5 text-red-600 hover:bg-red-50 disabled:cursor-not-allowed disabled:opacity-40"><Trash2 size={12}/></button></td></tr>)}</tbody></table></div></section>;
